// v154 — Manager › Tests : liste des testeurs, affectation aux périodes de tests des PJ, tests FAT à réaliser
// (interne toujours ; client et/ou NOBO selon la présence), d'après la checklist OP022-DP001-A.
// Les données vivent dans planning/tests (un seul document).
import React, { useMemo, useState } from "react";
import { T, FZF as FZ } from "../theme";
import { getPjMeta, PRESENCE_META, PresenceChip, presenceKind, presenceDates, presenceFirstDate, Avatar, personTint } from "../pjMeta";
import { fmt, toLocalISO } from "../parsers";
import { useMentions } from "../mentionContext";
import { CARD, H_TITLE, H_SUB, EmptyNote, PresenceEditor } from "./ManagerParts";
import { NavIcon } from "./SharedUI";
import { SECTIONS, DEFAULT_TEST_CATALOG, catalogOf, testersOf, planOf, activeSections, selectedIds, toggleTest, setExtra, assignTester, unassignTester, setAssignDates, effRange, findConflicts, assignmentsOf, dropTester, dropTestFromPlans, newId } from "../testPlan";

const FIELD = { padding: "5px 9px", borderRadius: 8, border: "1px solid " + T.line, background: T.card, color: T.ink900, fontSize: FZ.sm, fontFamily: T.font, minWidth: 0 };
const field = () => ({ ...FIELD, border: "1px solid " + T.line, background: T.card, color: T.ink900 });
const btn = (on = true, kind) => ({ border: kind === "ghost" ? "1px solid " + T.line : "none", borderRadius: 8, padding: "5px 12px", fontSize: FZ.xs, fontWeight: 700, fontFamily: T.font, cursor: on ? "pointer" : "default", background: kind === "ghost" ? T.card : on ? T.navy700 : T.ink100, color: kind === "ghost" ? T.ink700 : "#fff", flexShrink: 0 });
// mêmes couleurs que les pastilles de présence client / NOBO (lisibles en clair comme en sombre)
const SEC_COLOR = { interne: () => T.teal600, client: () => PRESENCE_META.client.ink, nobo: () => PRESENCE_META.nobo.ink };
const SEC_BORDER = { interne: () => T.teal500, client: () => PRESENCE_META.client.color, nobo: () => PRESENCE_META.nobo.color };
const dIso = x => { if (!x) return ""; const d = new Date(x); return isNaN(d) ? "" : toLocalISO(d); };
const fd = iso => iso ? fmt(new Date(iso)) : "—";
const period = r => r.tests ? fd(dIso(r.tests)) + (r.testsFin ? " → " + fd(dIso(r.testsFin)) : "") : "Période non définie";

export function TestsTab({ doc, save, data, clientPresence, setClientPresenceFor }) {
  const [sub, setSub] = useState("plan");
  const [msg, setMsg] = useState(null);
  const testers = testersOf(doc), catalog = catalogOf(doc);
  const rows = useMemo(() => (data || []).filter(r => r && r.pj && r.etat !== "SLOT_LIBRE"), [data]);
  const conflicts = useMemo(() => findConflicts(doc, rows), [doc, rows]);
  const commit = async next => { const ok = await save({ ...doc, ...next }); if (ok === false) setMsg("L'enregistrement a échoué."); else setMsg(null); return ok; };
  const nPlanned = rows.filter(r => planOf(doc, r.pj).assign.length).length;
  const SUBS = [["plan", "Planning des tests"], ["testers", "Testeurs (" + testers.length + ")"], ["catalog", "Catalogue des tests"]];
  return (<div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
    <div style={{ ...CARD, padding: "12px 16px", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap" }}>
      <div style={{ minWidth: 0 }}>
        <div style={H_TITLE}>Tests (FAT) : testeurs et tests à réaliser</div>
        <div style={H_SUB}>Affectez des testeurs aux périodes de tests et définissez, pour chaque PJ, les tests à faire en interne et avec le client et/ou NOBO.</div>
      </div>
      <div role="tablist" style={{ display: "inline-flex", background: T.surface, border: "1px solid " + T.line, borderRadius: 10, padding: 2, gap: 2 }}>
        {SUBS.map(([id, l]) => <button key={id} role="tab" aria-selected={sub === id} onClick={() => setSub(id)} style={{ border: "none", cursor: "pointer", borderRadius: 8, padding: "5px 12px", fontSize: FZ.xs, fontWeight: 700, fontFamily: T.font, background: sub === id ? T.card : "transparent", color: sub === id ? T.teal600 : T.ink500, boxShadow: sub === id ? T.shadowSm : "none" }}>{l}</button>)}
      </div>
    </div>
    {msg && <div role="alert" style={{ color: T.red500, fontSize: FZ.sm, fontWeight: 600 }}>{msg}</div>}
    {conflicts.length > 0 && sub === "plan" && <div role="status" style={{ background: T.amber100, color: T.amber600, borderRadius: 10, padding: "8px 12px", fontSize: FZ.sm, fontWeight: 600 }}>
      ⚠ {conflicts.length} chevauchement{conflicts.length > 1 ? "s" : ""} : {conflicts.slice(0, 4).map(c => { const t = testers.find(x => x.id === c.tid); return (t ? t.name : "Testeur") + " sur " + c.a.pj + " et " + c.b.pj; }).join(" · ")}{conflicts.length > 4 ? " …" : ""}
    </div>}
    {sub === "plan" && <PlanView {...{ doc, rows, testers, catalog, conflicts, commit, clientPresence, setClientPresenceFor, nPlanned }} />}
    {sub === "testers" && <TestersView {...{ doc, rows, testers, commit }} />}
    {sub === "catalog" && <CatalogView {...{ doc, catalog, commit }} />}
  </div>);
}

// ── Planning : une carte par PJ ayant une période de tests ───────────────────────────────────
function PlanView({ doc, rows, testers, catalog, conflicts, commit, clientPresence, setClientPresenceFor, nPlanned }) {
  const [past, setPast] = useState(false), [onlyFree, setOnlyFree] = useState(false), [q, setQ] = useState("");
  const todayIso = toLocalISO(new Date());
  const list = useMemo(() => rows.filter(r => r.tests).filter(r => past || (r.etat !== "SHIPPED" && (dIso(r.testsFin || r.tests) >= todayIso)))
    .filter(r => !onlyFree || !planOf(doc, r.pj).assign.length)
    .filter(r => { const s = q.trim().toLowerCase(); return !s || r.pj.toLowerCase().includes(s) || String(getPjMeta(r.pj, r).nomProjet || "").toLowerCase().includes(s); })
    .sort((a, b) => dIso(a.tests).localeCompare(dIso(b.tests))), [rows, doc, past, onlyFree, q, todayIso]);
  const noPeriod = rows.filter(r => !r.tests && r.etat !== "SHIPPED").length;
  return (<div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
    <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
      <input value={q} onChange={e => setQ(e.target.value)} placeholder="Rechercher un PJ, un projet…" style={{ ...field(), width: 240 }} />
      <label style={{ display: "inline-flex", gap: 6, alignItems: "center", fontSize: FZ.xs, fontWeight: 600, color: T.ink500, cursor: "pointer" }}><input type="checkbox" checked={onlyFree} onChange={e => setOnlyFree(e.target.checked)} />Sans testeur seulement</label>
      <label style={{ display: "inline-flex", gap: 6, alignItems: "center", fontSize: FZ.xs, fontWeight: 600, color: T.ink500, cursor: "pointer" }}><input type="checkbox" checked={past} onChange={e => setPast(e.target.checked)} />Inclure les tests passés / expédiés</label>
      <span style={{ fontSize: FZ.xs, color: T.ink300 }}>{list.length} PJ affiché{list.length > 1 ? "s" : ""} · {nPlanned} avec testeur{noPeriod ? " · " + noPeriod + " sans période de tests" : ""}</span>
    </div>
    {testers.length === 0 && <div style={{ ...CARD, padding: "10px 14px", fontSize: FZ.sm, color: T.ink500 }}>Aucun testeur dans la liste : ajoutez-les d'abord dans l'onglet « Testeurs ».</div>}
    {list.length === 0 && <EmptyNote>Aucun PJ à afficher.</EmptyNote>}
    {list.map(r => <PjCard key={r.pj} {...{ r, doc, testers, catalog, conflicts, commit, clientPresence, setClientPresenceFor }} />)}
  </div>);
}

function PjCard({ r, doc, testers, catalog, conflicts, commit, clientPresence, setClientPresenceFor }) {
  const [open, setOpen] = useState(false);
  const plan = planOf(doc, r.pj);
  const presence = (clientPresence && clientPresence[r.pj]) || r.clientPresence || null;
  const kind = presenceKind(presence);
  const act = activeSections(kind);
  const meta = getPjMeta(r.pj, r);
  const savePlan = p => commit({ plans: { ...(doc.plans || {}), [r.pj]: p } });
  const saveDates = (tid, from, to) => savePlan(setAssignDates(plan, tid, from, to));
  const free = testers.filter(t => !plan.assign.some(a => a.tid === t.id));
  const myConf = new Set(conflicts.filter(c => c.a.pj === r.pj || c.b.pj === r.pj).map(c => c.tid));
  const nTests = act.reduce((n, s) => n + selectedIds(plan, catalog, s).length, 0);
  const minD = dIso(r.tests), maxD = dIso(r.testsFin) || minD;
  return (<div style={{ ...CARD, overflow: "hidden" }}>
    <div onClick={() => setOpen(v => !v)} role="button" aria-expanded={open} tabIndex={0} onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setOpen(v => !v); } }}
      style={{ display: "grid", gridTemplateColumns: "minmax(120px,170px) minmax(150px,200px) auto 1fr auto", gap: 12, alignItems: "center", padding: "10px 14px", cursor: "pointer" }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ fontFamily: T.fontMono, fontWeight: 700, fontSize: FZ.sm, color: T.teal600 }}>{r.pj}</div>
        <div title={meta.nomProjet || ""} style={{ fontSize: FZ.xs, color: T.ink500, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{meta.nomProjet || ""}</div>
      </div>
      <div style={{ fontSize: FZ.sm, color: T.ink700, fontWeight: 600 }}>{period(r)}</div>
      <div>{kind ? <PresenceChip kind={kind} date={presenceFirstDate(presence)} dates={presenceDates(presence)} compact tiny fontSize={10.5} /> : <span style={{ fontSize: FZ.xs, color: T.ink300 }}>Interne seul</span>}</div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", minWidth: 0 }}>
        {plan.assign.length === 0 && <span style={{ fontSize: FZ.xs, color: T.ink300 }}>Aucun testeur affecté</span>}
        {plan.assign.map(a => { const t = testers.find(x => x.id === a.tid); if (!t) return null; return <TesterChip key={a.tid} t={t} warn={myConf.has(a.tid)} />; })}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, color: T.ink500, fontSize: FZ.xs, fontWeight: 600 }}>{nTests} test{nTests > 1 ? "s" : ""}<span style={{ transform: open ? "rotate(180deg)" : "none", display: "inline-flex" }}><NavIcon name="chevronDown" size={12} /></span></div>
    </div>
    {open && <div style={{ borderTop: "1px solid " + T.line, padding: "12px 14px", display: "flex", flexDirection: "column", gap: 14, background: T.surface }}>
      <div>
        <Cap>Testeurs affectés à la période de tests</Cap>
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 6 }}>
          {plan.assign.map(a => { const t = testers.find(x => x.id === a.tid); const eff = effRange(a, r); return (
            <div key={a.tid} style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ minWidth: 160 }}>{t ? <TesterChip t={t} warn={myConf.has(a.tid)} /> : <span style={{ color: T.ink300 }}>Testeur retiré</span>}</span>
              <label style={{ fontSize: FZ.xs, color: T.ink500, display: "inline-flex", gap: 4, alignItems: "center" }}>du <input type="date" value={a.from || ""} min={minD || undefined} max={maxD || undefined} onChange={e => saveDates(a.tid, e.target.value, a.to)} style={{ ...field(), padding: "3px 6px" }} /></label>
              <label style={{ fontSize: FZ.xs, color: T.ink500, display: "inline-flex", gap: 4, alignItems: "center" }}>au <input type="date" value={a.to || ""} min={minD || undefined} max={maxD || undefined} onChange={e => saveDates(a.tid, a.from, e.target.value)} style={{ ...field(), padding: "3px 6px" }} /></label>
              <span style={{ fontSize: FZ.xs, color: T.ink300 }}>{a.from || a.to ? "" : "toute la période : "}{fd(eff.from)} → {fd(eff.to)}</span>
              <button onClick={() => savePlan(unassignTester(plan, a.tid))} style={btn(true, "ghost")} aria-label={"Retirer " + (t ? t.name : "")}>Retirer</button>
            </div>); })}
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <select value="" onChange={e => { if (e.target.value) savePlan(assignTester(plan, e.target.value)); }} disabled={!free.length} style={{ ...field(), minWidth: 200 }} aria-label="Affecter un testeur">
              <option value="">{free.length ? "＋ Affecter un testeur…" : testers.length ? "Tous les testeurs sont affectés" : "Ajoutez des testeurs d'abord"}</option>
              {free.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
            </select>
          </div>
        </div>
      </div>
      <div>
        <Cap>Présence aux tests</Cap>
        <div style={{ marginTop: 6 }}>{setClientPresenceFor ? <PresenceEditor r={r} presence={presence} onChange={v => setClientPresenceFor(r.pj, v)} /> : <span style={{ fontSize: FZ.xs, color: T.ink500 }}>{kind ? "Présence enregistrée" : "Aucune présence"}</span>}</div>
      </div>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(280px,1fr))", gap: 10 }}>
        {SECTIONS.map(([k, label, hint]) => {
          const on = act.includes(k), ids = selectedIds(plan, catalog, k), col = SEC_COLOR[k]();
          return (<div key={k} style={{ background: T.card, border: "1px solid " + (on ? SEC_BORDER[k]() : T.line), borderRadius: 10, padding: "8px 10px", opacity: on ? 1 : .55, minWidth: 0 }}>
            <div style={{ display: "flex", justifyContent: "space-between", gap: 6, alignItems: "baseline" }}>
              <span style={{ fontSize: FZ.sm, fontWeight: 800, color: col }}>{label}</span>
              <span style={{ fontSize: FZ.xs, color: T.ink300 }}>{on ? ids.length + "/" + catalog[k].length : "non applicable"}</span>
            </div>
            <div style={{ fontSize: FZ.xs, color: T.ink300, marginBottom: 4 }}>{on ? hint : "Définissez la présence " + (k === "client" ? "du client" : "de NOBO") + " pour activer cette partie."}</div>
            {on && <>
              {catalog[k].map(tst => <label key={tst.id} title={tst.obj} style={{ display: "flex", gap: 6, alignItems: "flex-start", padding: "2px 0", fontSize: FZ.xs, color: T.ink700, cursor: "pointer" }}>
                <input type="checkbox" checked={ids.includes(tst.id)} onChange={() => savePlan(toggleTest(plan, catalog, k, tst.id))} style={{ marginTop: 2 }} /><span>{tst.name}</span></label>)}
              {catalog[k].length === 0 && <div style={{ fontSize: FZ.xs, color: T.ink300 }}>Aucun test dans le catalogue.</div>}
              <input defaultValue={plan.extra[k] || ""} key={r.pj + k + (plan.extra[k] || "")} onBlur={e => { if (e.target.value !== (plan.extra[k] || "")) savePlan(setExtra(plan, k, e.target.value)); }} placeholder="Autre test (texte libre)" maxLength={300} style={{ ...field(), width: "100%", boxSizing: "border-box", marginTop: 4, fontSize: FZ.xs }} />
            </>}
          </div>);
        })}
      </div>
    </div>}
  </div>);
}

const Cap = ({ children }) => <div style={{ fontSize: FZ.xs, fontWeight: 700, color: T.ink500, textTransform: "uppercase", letterSpacing: ".05em" }}>{children}</div>;
function TesterChip({ t, warn }) {
  return (<span title={warn ? "Chevauchement avec un autre PJ" : t.email || t.name} style={{ display: "inline-flex", alignItems: "center", gap: 5, background: warn ? T.amber100 : T.card, border: "1px solid " + (warn ? T.amber500 : T.line), borderRadius: 999, padding: "1px 9px 1px 3px", fontSize: FZ.xs, fontWeight: 700, color: warn ? T.amber600 : T.ink700 }}>
    <Avatar name={t.name} tint={personTint(t.name)[0]} size={18} />{t.name}{warn ? " ⚠" : ""}
  </span>);
}

// ── Testeurs ─────────────────────────────────────────────────────────────────────────────────
function TestersView({ doc, rows, testers, commit }) {
  const ctx = useMentions();
  const [name, setName] = useState(""), [email, setEmail] = useState(""), [del, setDel] = useState(null);
  const acct = ctx.options.find(o => o.name.toLowerCase() === name.trim().toLowerCase());
  const add = async () => { const n = name.trim(); if (!n || testers.some(t => t.name.toLowerCase() === n.toLowerCase())) return; const ok = await commit({ testers: [...testers, { id: newId("t"), name: n, email: (email || (acct && acct.email) || "").trim() }] }); if (ok !== false) { setName(""); setEmail(""); } };
  const upd = (id, patch) => commit({ testers: testers.map(t => t.id === id ? { ...t, ...patch } : t) });
  return (<div style={{ ...CARD, padding: 14, display: "flex", flexDirection: "column", gap: 12 }}>
    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
      <input list="tester-accounts" value={name} onChange={e => setName(e.target.value)} onKeyDown={e => { if (e.key === "Enter") add(); }} placeholder="Nom du testeur (ou compte connecté)" style={{ ...field(), width: 260 }} />
      <datalist id="tester-accounts">{ctx.options.map(o => <option key={o.email} value={o.name}>{o.email}</option>)}</datalist>
      <input value={email || (acct ? acct.email : "")} onChange={e => setEmail(e.target.value)} placeholder="E-mail (facultatif)" style={{ ...field(), width: 240 }} />
      <button onClick={add} disabled={!name.trim()} style={btn(!!name.trim())}>Ajouter le testeur</button>
    </div>
    {testers.length === 0 && <EmptyNote>Aucun testeur pour l'instant.</EmptyNote>}
    {testers.map(t => { const as = assignmentsOf(doc, t.id, rows); return (
      <div key={t.id} style={{ display: "grid", gridTemplateColumns: "minmax(180px,240px) minmax(180px,240px) 1fr auto", gap: 10, alignItems: "center", borderTop: "1px solid " + T.surface, paddingTop: 8 }}>
        <input defaultValue={t.name} key={t.id + t.name} onBlur={e => { const v = e.target.value.trim(); if (v && v !== t.name) upd(t.id, { name: v }); }} style={field()} aria-label="Nom" />
        <input defaultValue={t.email || ""} key={t.id + (t.email || "")} onBlur={e => { if (e.target.value.trim() !== (t.email || "")) upd(t.id, { email: e.target.value.trim() }); }} placeholder="E-mail" style={field()} aria-label="E-mail" />
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", fontSize: FZ.xs, color: T.ink500 }}>
          {as.length === 0 ? <span style={{ color: T.ink300 }}>Aucune affectation</span> : as.map(a => <span key={a.pj} style={{ background: T.surface, borderRadius: 6, padding: "2px 8px", fontWeight: 600 }}><b style={{ fontFamily: T.fontMono, color: T.teal600 }}>{a.pj}</b> {fd(a.from)} → {fd(a.to)}</span>)}
        </div>
        {del === t.id
          ? <span style={{ display: "inline-flex", gap: 6 }}><button onClick={() => { setDel(null); commit(dropTester(doc, t.id)); }} style={{ ...btn(true), background: T.red500 }}>Confirmer</button><button onClick={() => setDel(null)} style={btn(true, "ghost")}>Annuler</button></span>
          : <button onClick={() => setDel(t.id)} style={btn(true, "ghost")}>Retirer</button>}
      </div>); })}
  </div>);
}

// ── Catalogue des tests (FAT interne / client / NOBO) ───────────────────────────────────────
function CatalogView({ doc, catalog, commit }) {
  const [del, setDel] = useState(null), [reset, setReset] = useState(false);
  const setSec = (k, list) => commit({ catalog: { ...catalog, [k]: list } });
  const move = (k, i, d) => { const l = [...catalog[k]]; const j = i + d; if (j < 0 || j >= l.length) return; [l[i], l[j]] = [l[j], l[i]]; setSec(k, l); };
  return (<div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
    <div style={{ ...CARD, padding: "10px 14px", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
      <span style={{ fontSize: FZ.sm, color: T.ink500 }}>Tests proposés pour chaque PJ (modèle OP022-DP001-A). On coche ensuite ceux à réaliser pour chaque PJ dans « Planning des tests ».</span>
      {reset ? <span style={{ display: "inline-flex", gap: 6 }}><button onClick={() => { setReset(false); commit({ catalog: DEFAULT_TEST_CATALOG }); }} style={{ ...btn(true), background: T.red500 }}>Rétablir le modèle</button><button onClick={() => setReset(false)} style={btn(true, "ghost")}>Annuler</button></span>
        : <button onClick={() => setReset(true)} style={btn(true, "ghost")}>Rétablir le modèle du fichier</button>}
    </div>
    {SECTIONS.map(([k, label, hint]) => (<div key={k} style={{ ...CARD, padding: 14, display: "flex", flexDirection: "column", gap: 8 }}>
      <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}><span style={{ fontSize: FZ.md, fontWeight: 800, color: SEC_COLOR[k]() }}>{label}</span><span style={{ fontSize: FZ.xs, color: T.ink300 }}>{hint}</span></div>
      {catalog[k].map((t, i) => (<div key={t.id} style={{ display: "grid", gridTemplateColumns: "minmax(200px,300px) 1fr auto", gap: 8, alignItems: "start" }}>
        <input defaultValue={t.name} key={t.id + t.name} onBlur={e => { const v = e.target.value.trim(); if (v && v !== t.name) setSec(k, catalog[k].map(x => x.id === t.id ? { ...x, name: v } : x)); }} style={field()} aria-label="Nom du test" />
        <textarea defaultValue={t.obj || ""} key={t.id + "o" + (t.obj || "")} rows={2} onBlur={e => { if (e.target.value !== (t.obj || "")) setSec(k, catalog[k].map(x => x.id === t.id ? { ...x, obj: e.target.value } : x)); }} placeholder="Objectifs du test" style={{ ...field(), resize: "vertical" }} aria-label="Objectifs" />
        <span style={{ display: "inline-flex", gap: 4 }}>
          <button onClick={() => move(k, i, -1)} disabled={i === 0} style={btn(i > 0, "ghost")} aria-label="Monter">↑</button>
          <button onClick={() => move(k, i, 1)} disabled={i === catalog[k].length - 1} style={btn(i < catalog[k].length - 1, "ghost")} aria-label="Descendre">↓</button>
          {del === t.id
            ? <><button onClick={() => { setDel(null); commit({ ...dropTestFromPlans(doc, k, t.id), catalog: { ...catalog, [k]: catalog[k].filter(x => x.id !== t.id) } }); }} style={{ ...btn(true), background: T.red500 }}>Confirmer</button><button onClick={() => setDel(null)} style={btn(true, "ghost")}>Non</button></>
            : <button onClick={() => setDel(t.id)} style={btn(true, "ghost")}>Supprimer</button>}
        </span>
      </div>))}
      <div><button onClick={() => setSec(k, [...catalog[k], { id: newId(k[0]), name: "Nouveau test", obj: "" }])} style={btn(true, "ghost")}>＋ Ajouter un test</button></div>
    </div>))}
  </div>);
}
